// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 value, bytes memory data) public {
        value = bound(value, 0, 1 ether);

        Reverter bad = new Reverter();

        vm.deal(address(c), 1 ether);

        bool ok;
        try c.sendMoney(address(bad), value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        if (value == 0) {
            assertTrue(true);
        } else {
            assertTrue(!ok);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("bad");
    }
}
